      cover: 'media/af1c2c3d-1612-4ab0-92ab-f51cd1dfa193.jpeg',
      name: { ru: 'The Rabbit: Creation of the Mind', en: 'The Rabbit: Creation of the Mind', es: 'The Rabbit: Creation of the Mind', de: 'The Rabbit: Creation of the Mind', fr: 'The Rabbit: Creation of the Mind', it: 'The Rabbit: Creation of the Mind', pt: 'The Rabbit: Creation of the Mind', zh: 'The Rabbit: Creation of the Mind', ja: 'The Rabbit: Creation of the Mind' },
